  const[viewDoc,setViewDoc]=useState(null);const[viewItems,setViewItems]=useState([]);const[viewType,setViewType]=useState("");
  const[nuUser,setNuUser]=useState("");const[nuPass,setNuPass]=useState("");const[nuName,setNuName]=useState("");const[nuEmail,setNuEmail]=useState("");const[nuRole,setNuRole]=useState("regular");
