  const role=user?.role||"regular";const R=action=>can(role,action);
  const calcSub=it=>it.reduce((s,i)=>s+i.qty*i.rate,0);const calcTax=it=>it.reduce((s,i)=>s+Math.round(i.qty*i.rate*i.gst/100*100)/100,0);const calcTot=it=>calcSub(it)+calcTax(it);
  const resetForm=()=>{setFrmParty({...emptyParty});setFrmDate(new Date().toISOString().slice(0,10));setFrmDue("");setFrmItems([{desc:"",hsn:"",qty:1,rate:0,gst:18}]);setFrmNotes("");setFrmType("intra");setFrmProj("");setFrmTerms("");setFrmErr("");setFrmPO("");};
