  const applyPreset=p=>{setFPreset(p);const now=new Date(),y=now.getFullYear(),m=now.getMonth();if(p==="all"){setFDateFrom("");setFDateTo("");}else if(p==="today"){const d=now.toISOString().slice(0,10);setFDateFrom(d);setFDateTo(d);}else if(p==="thisMonth"){setFDateFrom(`${y}-${String(m+1).padStart(2,'0')}-01`);setFDateTo(now.toISOString().slice(0,10));}else if(p==="thisYear"){setFDateFrom(`${y}-01-01`);setFDateTo(now.toISOString().slice(0,10));}else if(p==="last7"){const s=new Date(now);s.setDate(now.getDate()-7);setFDateFrom(s.toISOString().slice(0,10));setFDateTo(now.toISOString().slice(0,10));}else if(p==="last30"){const s=new Date(now);s.setDate(now.getDate()-30);setFDateFrom(s.toISOString().slice(0,10));setFDateTo(now.toISOString().slice(0,10));}};
