  const hasF=!!(fDateFrom||fDateTo||fProject!=="all"||fPerson!=="all"||fType!=="all");
  const fSbp=code=>ftxs.filter(t=>t.project===code&&t.kind==="project_expense"&&!t.settled&&!t.isReversal).reduce((s,t)=>s+t.amount,0);
  const fpx={fp:fPreset,ap:applyPreset,ff:fDateFrom,sff:setFDateFrom,ft:fDateTo,sft:setFDateTo,fpr:fProject,sfpr:setFProject,fpe:fPerson,sfpe:setFPerson,fty:fType,sfty:setFType,projects,people,cf:clearF,hf:hasF,ftxs,txs,sfp:setFPreset};
  const expCats=expenseCategories.length?expenseCategories.map(c=>c.name):GCATS;
  // Reconciliation: past debits sourced from reserve / project funds (to be normalized to "available")
  const recReserveTxs=txs.filter(t=>t.fundSource==="reserve"&&!t.settled&&!t.isReversal&&t.kind!=="income"&&t.kind!=="jv_reversal");
  const recProjFundTxs=txs.filter(t=>t.fundSource&&t.fundSource!=="available"&&t.fundSource!=="reserve"&&!t.settled&&!t.isReversal&&t.kind!=="jv_reversal");
  const recReserveSum=recReserveTxs.reduce((s,t)=>s+t.amount,0);const recProjFundSum=recProjFundTxs.reduce((s,t)=>s+t.amount,0);
  // Bank import: parse mapped rows into proposed transactions (+ duplicate flag)
  const biParsed=biData.map((r,idx)=>{
    const date=normDate(biColDate!==""?r[Number(biColDate)]:"");
    const desc=biColDesc!==""?(r[Number(biColDesc)]||"").trim():"";
    let amount=0,kind="";
    if(biMode==="signed"){const v=biColAmt!==""?parseAmt(r[Number(biColAmt)]):0;amount=Math.abs(v);kind=v<0?"debit":"credit";}
    else{const dr=biColDebit!==""?Math.abs(parseAmt(r[Number(biColDebit)])):0;const cr=biColCredit!==""?Math.abs(parseAmt(r[Number(biColCredit)])):0;if(dr>0){amount=dr;kind="debit";}else{amount=cr;kind="credit";}}
    const dup=!!date&&txs.some(t=>t.date===date&&Math.abs((t.amount||0)-amount)<0.01&&(t.note||"").toLowerCase()===desc.toLowerCase());
    return{idx,date,desc,amount,kind,dup};
  }).filter(p=>p.amount>0&&p.date);
  const biSelected=biParsed.filter(p=>!biSkip[p.idx]);
  const totAlloc=projects.reduce((s,p)=>s+(p.alloc||0),0);const totExp=txs.filter(t=>ek(t)!=="income"&&ek(t)!=="jv_reversal"&&!t.settled&&!t.isReversal).reduce((s,t)=>s+t.amount,0);const totInc=txs.filter(t=>t.kind==="income"&&!t.settled&&!t.isReversal).reduce((s,t)=>s+t.amount,0);
  // Available Funds is now tied directly to the bank balance. Reserve & Allocated are display-only labels.
  const availBal=bal;const excess=bal;const totExtra=Object.values(allocs).reduce((s,v)=>s+Number(v||0),0);
  const b2bInvs=invoices.filter(i=>i.source==="b2b");const b2cInvs=invoices.filter(i=>i.source==="b2c");
  const projChart=projects.map(p=>({name:p.name.slice(0,12),spent:txs.filter(t=>t.project===p.code&&t.kind==="project_expense"&&!t.settled&&!t.isReversal).reduce((s,t)=>s+t.amount,0),budget:p.alloc||0,color:p.color||"#6366f1"}));
  const catChart=expCats.map((cat,i)=>({name:cat,value:ftxs.filter(t=>t.category===cat&&ek(t)!=="income"&&!t.settled&&!t.isReversal).reduce((s,t)=>s+t.amount,0),color:VIBRANT[i%VIBRANT.length]})).filter(c=>c.value>0);
  const personChart=people.map(p=>({name:p.name,spent:ftxs.filter(t=>t.person===p.name&&ek(t)!=="income"&&ek(t)!=="jv_reversal"&&!t.settled&&!t.isReversal).reduce((s,t)=>s+t.amount,0)})).filter(p=>p.spent>0).sort((a,b)=>b.spent-a.spent);
  const fundChart=(()=>{const bk={available:0,reserve:0};ftxs.filter(t=>ek(t)!=="income"&&!t.settled&&!t.isReversal).forEach(t=>{const fs=t.fundSource||"available";if(fs==="reserve")bk.reserve+=t.amount;else if(fs==="available")bk.available+=t.amount;else bk[fs]=(bk[fs]||0)+t.amount;});return Object.entries(bk).filter(([,v])=>v>0).map(([k,v])=>({name:k==="reserve"?"Reserve":k==="available"?"Available":(projects.find(p=>p.code===k)?.name||k),value:v,color:k==="reserve"?FUND_CLR.reserve:k==="available"?FUND_CLR.available:(projects.find(p=>p.code===k)?.color||FUND_CLR.project)}));})();
  const monthlyTrend=(()=>{const m={};ftxs.forEach(t=>{const mo=t.date?.slice(0,7);if(!mo)return;if(!m[mo])m[mo]={month:mo,income:0,expense:0};if(t.kind==="income"&&!t.settled&&!t.isReversal)m[mo].income+=t.amount;else if(ek(t)!=="jv_reversal"&&!t.settled&&!t.isReversal)m[mo].expense+=t.amount;});return Object.values(m).sort((a,b)=>a.month.localeCompare(b.month)).map(v=>({...v,label:MONTHS[parseInt(v.month.slice(5,7))-1]+" '"+v.month.slice(2,4)}));})();
  const ChartTip=({active,payload,label:lb})=>active&&payload?(<div className="bg-white rounded-xl shadow-xl border border-gray-100 p-3 text-sm"><p className="font-semibold text-gray-800 mb-1">{lb||payload[0]?.payload?.name}</p>{payload.map((p,i)=>(<div key={i} className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full flex-shrink-0" style={{backgroundColor:p.color||p.fill}}/><span className="text-gray-500">{p.dataKey||p.name}:</span><span className="font-semibold text-gray-800">{fmt(p.value)}</span></div>))}</div>):null;

  // ===== ACTIONS =====
  const addProj=async()=>{if(!npN||!npB)return;setSaving(true);await db.addProject({name:npN,code:gc(npN),fixed:Number(npB),alloc:Number(npB),color:npC});await log("create","project",null,"Created: "+npN);await loadAll();setNpN("");setNpB("");setNpC("#6366f1");setSaving(false);setModal(null);};
  const svProj=async()=>{setSaving(true);await db.updateProject(epId,{name:epN,fixed:Number(epA),alloc:Number(epA),color:epC});await log("edit","project",epId,"Edited: "+epN);await loadAll();setSaving(false);setModal(null);};
  const addPe=async()=>{if(!npName)return;setSaving(true);await db.addPerson({name:npName,role:npRole||"Member"});await log("create","person",null,"Added: "+npName);await loadAll();setNpName("");setNpRole("");setSaving(false);setModal(null);};
  const svPe=async()=>{setSaving(true);const on=people.find(p=>p.id===ePId)?.name;await db.updatePerson(ePId,{name:ePName,role:ePRole});if(on&&on!==ePName)await db.updateTransactionsPerson(on,ePName);await log("edit","person",ePId,"Edited: "+ePName);await loadAll();setSaving(false);setModal(null);};

  // *** Transaction with fund source (available / reserve / project fund) ***
  const isProjectFund=ntFund!=="available"&&ntFund!=="reserve";
  const addTx=async()=>{if(!ntA||!ntPe)return;if(ntKind==="debit"&&isProjectFund&&!ntFund)return;setSaving(true);const amt=Number(ntA);
    const projCode=ntKind==="debit"?(isProjectFund?ntFund:ntP):"";
    const ak=ntKind==="credit"?"income":(projCode?"project_expense":"general_expense");
    await db.addTransaction({date:ntD,project:projCode,person:ntPe,amount:amt,kind:ak,category:ntCat||"",note:ntNo,fundSource:ntKind==="debit"?ntFund:"available"});
    const fb=await db.getBalance();
    if(ntKind==="credit"){await db.updateBalance((fb.balance||0)+amt,null);}
    else if(ntFund==="reserve"){
      // Reserve is display-only now: a reserve debit reduces the bank balance (and the reserve label).
      await db.updateBalance((fb.balance||0)-amt,Math.max(0,(fb.liquid_reserve||0)-amt));
    }else if(isProjectFund){
      // Deduct from both bal and project allocation
      await db.updateBalance((fb.balance||0)-amt,null);
      const pr=projects.find(p=>p.code===ntFund);
      if(pr)await db.updateProject(pr.id,{name:pr.name,fixed:pr.fixed,alloc:Math.max(0,(pr.alloc||0)-amt),color:pr.color});
    }else{
      await db.updateBalance((fb.balance||0)-amt,null);
    }
    const fundLabel=ntFund==="reserve"?"Reserve":(isProjectFund?(projects.find(p=>p.code===ntFund)?.name||ntFund):"Available");
    await log("create","transaction",null,kl(ak)+" "+fmt(amt)+(ntKind==="debit"?" from "+fundLabel:""));
    await loadAll();setNtD(new Date().toISOString().slice(0,10));setNtP("");setNtPe("");setNtA("");setNtKind("debit");setNtNo("");setNtCat("");setNtFund("available");setSaving(false);setModal(null);};

  const doSettle=async()=>{if(!settleTx)return;setSaving(true);await db.settleTransaction(settleTx.id);const src=settleTx.fundSource||"available";await db.addTransaction({date:new Date().toISOString().slice(0,10),project:settleTx.project||"",person:settleTx.person,amount:settleTx.amount,kind:"jv_reversal",category:"JV",note:"REVERSAL: "+(settleNote||fmt(settleTx.amount)),isReversal:true,originalId:settleTx.id,fundSource:src});const fb=await db.getBalance();const amt=settleTx.amount;if(settleTx.kind==="income"){await db.updateBalance((fb.balance||0)-amt,null);}else if(src==="reserve"){await db.updateBalance((fb.balance||0)+amt,(fb.liquid_reserve||0)+amt);}else if(src!=="available"){const pr=projects.find(p=>p.code===src);await db.updateBalance((fb.balance||0)+amt,null);if(pr)await db.updateProject(pr.id,{name:pr.name,fixed:pr.fixed,alloc:(pr.alloc||0)+amt,color:pr.color});}else{await db.updateBalance((fb.balance||0)+amt,null);}await log("settle","transaction",settleTx.id,"JV "+fmt(amt)+" → "+src);await loadAll();setSaving(false);setSettleTx(null);setSettleNote("");setModal(null);};
  const applyAllocs=async()=>{setSaving(true);for(const p of projects){const e=Number(allocs[p.id]||0);if(e>0)await db.updateProject(p.id,{name:p.name,fixed:p.fixed,alloc:(p.alloc||0)+e,color:p.color});}await log("allocate","budget",null,"Allocated "+fmt(totExtra));await loadAll();setAllocs({});setSaving(false);};
  // *** Edit transaction tags ONLY — never changes amount/type/fund/balance ***
  const startEditTx=t=>{setEtId(t.id);setEtDate(t.date);setEtPerson(t.person||"");setEtCat(t.category||"");setEtProj(t.project||"");setEtNote(t.note||"");setModal("editTx");};
  const saveEditTx=async()=>{if(!etId)return;setSaving(true);await db.updateTransactionMeta(etId,{date:etDate,person:etPerson,category:etCat,project:etProj,note:etNote});await log("edit","transaction",etId,"Edited tags"+(etProj?(" → "+(projects.find(p=>p.code===etProj)?.name||etProj)):""));await loadAll();setEtId(null);setSaving(false);setModal(null);};
  const addExpCat=async()=>{if(!newExpCat.trim())return;setSaving(true);await db.addExpenseCategory(newExpCat.trim());await log("create","category",null,"Category: "+newExpCat.trim());await loadAll();setNewExpCat("");setSaving(false);};
  const rmExpCat=async(c)=>{setSaving(true);await db.deleteExpenseCategory(c.id);await log("remove","category",c.id,"Removed category: "+c.name);await loadAll();setSaving(false);};
  // *** One-time bank reconciliation: set Total Balance to the true bank figure, normalize fund tags, zero the reserve ***
  const doReconcile=async()=>{if(recTrueBal===""||isNaN(Number(recTrueBal)))return;setSaving(true);const trueBal=Number(recTrueBal);
    for(const t of [...recReserveTxs,...recProjFundTxs]){await db.updateTransactionFundSource(t.id,"available");}
    const fb=await db.getBalance();const delta=trueBal-(fb.balance||0);
    if(delta!==0)await db.addTransaction({date:new Date().toISOString().slice(0,10),project:"",person:user.displayName,amount:Math.abs(delta),kind:delta>0?"income":"general_expense",category:"Adjustment",note:"Bank reconciliation: set Total Balance to "+fmt(trueBal),fundSource:"available"});
    await db.updateBalance(trueBal,0);
    await log("settle","balance",null,"Reconciled balance to "+fmt(trueBal)+(delta?(" (adj "+fmt(delta)+")"):"")+"; normalized "+(recReserveTxs.length+recProjFundTxs.length)+" txns; reserve→0");
    await loadAll();setRecTrueBal("");setSaving(false);setModal(null);};
  // *** Bank statement CSV import ***
  const resetBankImport=()=>{setBiStep("upload");setBiFileName("");setBiHeaders([]);setBiData([]);setBiMode("signed");setBiColDate("");setBiColDesc("");setBiColAmt("");setBiColDebit("");setBiColCredit("");setBiColBal("");setBiSkip({});setBiCloseBal("");};
  const handleBankFile=async(file)=>{if(!file)return;const text=await file.text();const rows=parseCSV(text);if(rows.length<2)return;const headers=rows[0];const data=rows.slice(1);setBiFileName(file.name);setBiHeaders(headers);setBiData(data);
    const find=(...keys)=>{const i=headers.findIndex(h=>keys.some(k=>(h||"").toLowerCase().includes(k)));return i>=0?String(i):"";};
    setBiColDate(find("date"));setBiColDesc(find("desc","narration","particular","detail","remark"));
    const drI=find("debit","withdraw");const crI=find("credit","deposit");
    if(drI!==""||crI!==""){setBiMode("debitcredit");setBiColDebit(drI);setBiColCredit(crI);setBiColAmt("");}else{setBiMode("signed");setBiColAmt(find("amount"));}
    setBiColBal(find("balance"));setBiSkip({});setBiStep("map");};
  const doBankImport=async()=>{const rows=biParsed.filter(p=>!biSkip[p.idx]);if(!rows.length)return;setSaving(true);
    await db.addTransactionsBulk(rows.map(p=>({date:p.date,project:"",person:user.displayName,amount:p.amount,kind:p.kind==="credit"?"income":"general_expense",category:"Bank Import",note:p.desc,fundSource:"available"})));
    const fb=await db.getBalance();let newBal;
    if(biCloseBal!==""&&!isNaN(Number(biCloseBal)))newBal=Number(biCloseBal);
    else{const net=rows.reduce((s,p)=>s+(p.kind==="credit"?p.amount:-p.amount),0);newBal=(fb.balance||0)+net;}
    await db.updateBalance(newBal,null);
    await log("create","import",null,"Imported "+rows.length+" bank rows; balance → "+fmt(newBal));
    await loadAll();resetBankImport();setSaving(false);setModal(null);};

  // *** Reserve: ADD not replace ***
  const updateReserve=async()=>{if(!lIn)return;const addAmt=Number(lIn);const newTotal=liq+addAmt;setSaving(true);await db.updateBalance(null,newTotal);await log("reserve","budget",null,"Reserve +"+fmt(addAmt)+" = "+fmt(newTotal)+(lNote?" ("+lNote+")":""));await loadAll();setLIn("");setLNote("");setSaving(false);};

  const executeRemove=async()=>{if(!rmTarget)return;setSaving(true);await db.addRemoval({date:new Date().toISOString().slice(0,10),time:new Date().toLocaleTimeString(),type:rmTarget.type,label:rmTarget.label,detail:rmTarget.detail,reason:rmReason});if(rmTarget.type==="project")await db.deleteProject(rmTarget.id);else if(rmTarget.type==="person")await db.deletePerson(rmTarget.id);else if(rmTarget.type==="invoice")await db.deleteInvoice(rmTarget.id);else if(rmTarget.type==="product")await db.deleteProduct(rmTarget.id);else if(rmTarget.type==="inv_product")await db.deleteInventoryProduct(rmTarget.id);await log("remove",rmTarget.type,rmTarget.id,"Removed "+rmTarget.label);await loadAll();setSaving(false);setRmTarget(null);setRmReason("");setModal(null);};

  // Products
  const saveProd=async()=>{if(!pName)return;setSaving(true);const d={name:pName,productType:pType,category:pCat,unit:pUnit,price:Number(pPrice)||0,hsnCode:pHsn,taxPercent:Number(pTax)||18,description:pDesc};if(pEditId){await db.updateProduct(pEditId,d);await log("edit","product",pEditId,"Edited: "+pName);}else{await db.addProduct(d);await log("create","product",null,"Product: "+pName);}await loadAll();resetProd();setSaving(false);setModal(null);};

  // ===== INVENTORY ACTIONS =====
  const resetInvCat=()=>{setIcName("");setIcDesc("");setIcColor("#6366f1");setIcEditId(null);};
  const resetInvProd=()=>{setIpName("");setIpSku("");setIpCat("");setIpUnit("pcs");setIpBuyPrice("");setIpSellPrice("");setIpMinStock("");setIpDesc("");setIpHsn("");setIpTax("18");setIpProdType("Product");setIpEditId(null);};
  const generateSku=(catId)=>{const cat=invCats.find(c=>c.id===catId);const prefix=cat?cat.name.replace(/[^A-Za-z0-9]/g,"").slice(0,3).toUpperCase():"GEN";const existing=invProds.filter(p=>p.sku&&p.sku.startsWith(prefix+"-")).map(p=>{const n=parseInt(p.sku.split("-").pop(),10);return isNaN(n)?0:n;});const next=(existing.length?Math.max(...existing):0)+1;return prefix+"-"+String(next).padStart(3,"0");};
  const resetStockForm=()=>{setSiProduct("");setSiQty("");setSiCost("");setSiFund("available");setSiNotes("");setSiType("stock_in");};

  const saveInvCat=async()=>{if(!icName)return;setSaving(true);if(icEditId){await db.updateInventoryCategory(icEditId,{name:icName,description:icDesc,color:icColor});await log("edit","inventory_category",icEditId,"Edited: "+icName);}else{await db.addInventoryCategory({name:icName,description:icDesc,color:icColor});await log("create","inventory_category",null,"Category: "+icName);}await loadAll();resetInvCat();setSaving(false);setModal(null);};

  const saveInvProd=async()=>{if(!ipName)return;setSaving(true);const cat=invCats.find(c=>c.id===ipCat);const d={name:ipName,sku:ipSku,categoryId:ipCat||null,categoryName:cat?.name||"",unit:ipUnit,buyingPrice:Number(ipBuyPrice)||0,sellingPrice:Number(ipSellPrice)||0,minStock:Number(ipMinStock)||0,description:ipDesc,hsnCode:ipHsn,taxPercent:Number(ipTax)||18,productType:ipProdType};if(ipEditId){await db.updateInventoryProduct(ipEditId,d);await log("edit","inventory_product",ipEditId,"Edited: "+ipName);}else{d.currentStock=0;await db.addInventoryProduct(d);await log("create","inventory_product",null,"Inv Product: "+ipName);}await loadAll();resetInvProd();setSaving(false);setModal(null);};

  const executeStockMovement=async()=>{if(!siProduct||!siQty)return;setSaving(true);const prod=invProds.find(p=>p.id===siProduct);if(!prod){setSaving(false);return;}
    const qty=Number(siQty);const cost=Number(siCost)||prod.buying_price;const total=qty*cost;
    let fundLabel="Available";
    if(siType==="stock_in"){
      // Deduct from balance
      const fb=await db.getBalance();
      if(siFund==="reserve"){await db.updateBalance((fb.balance||0)-total,Math.max(0,(fb.liquid_reserve||0)-total));fundLabel="Reserve";}
      else if(siFund!=="available"){const pr=projects.find(p=>p.code===siFund);fundLabel=pr?pr.name:siFund;await db.addTransaction({date:new Date().toISOString().slice(0,10),project:siFund,person:user.displayName,amount:total,kind:"project_expense",category:"Inventory",note:"Stock In: "+prod.name+" x"+qty,fundSource:"available"});await db.updateBalance((fb.balance||0)-total,null);}
      else{await db.updateBalance((fb.balance||0)-total,null);}
      await db.updateInventoryStock(prod.id,(prod.current_stock||0)+qty);
    }else if(siType==="stock_out"){
      await db.updateInventoryStock(prod.id,Math.max(0,(prod.current_stock||0)-qty));fundLabel="N/A";
    }else{
      // adjustment — set absolute
      await db.updateInventoryStock(prod.id,qty);fundLabel="Adjustment";
    }
    await db.addInventoryTransaction({productId:prod.id,productName:prod.name,type:siType,quantity:qty,unitCost:cost,totalCost:siType==="stock_in"?total:0,fundSource:siType==="stock_in"?siFund:"",fundLabel,notes:siNotes,performedBy:user.displayName});
    await log(siType,"inventory",prod.id,prod.name+" x"+qty+(siType==="stock_in"?" from "+fundLabel:""));
    await loadAll();resetStockForm();setSaving(false);setModal(null);};

  // Invoice stock deduction
  const deductInvFromInvoice=async(invNumber,lineItems)=>{for(const it of lineItems){const ip=invProds.find(p=>p.is_active!==false&&p.name.toLowerCase()===it.desc.toLowerCase());if(ip){await db.updateInventoryStock(ip.id,Math.max(0,(ip.current_stock||0)-it.qty));await db.addInventoryTransaction({productId:ip.id,productName:ip.name,type:"stock_out",quantity:it.qty,unitCost:it.rate,totalCost:it.qty*it.rate,fundSource:"",fundLabel:"Invoice",notes:"Invoice "+invNumber,performedBy:user.displayName});}}};

  const viewInvProductHistory=async(prod)=>{const txns=await db.getInventoryTransactionsByProduct(prod.id);setInvViewProd(prod);setInvProdTxns(txns);setModal("invHistory");};

  const getStockBadge=(p)=>{if(p.current_stock<=0)return{cl:"stock-badge-out",label:"Out of Stock"};if(p.current_stock<=p.min_stock)return{cl:"stock-badge-low",label:"Low Stock"};return{cl:"stock-badge-ok",label:"In Stock"};};

  // Inventory computed values
  const activeInvProds=invProds.filter(p=>p.is_active!==false);
  const searchableProducts=activeInvProds.map(p=>({...p,product_type:p.product_type||"Product",category:p.category_name||"",price:p.selling_price||0,hsn_code:p.hsn_code||"",tax_percent:p.tax_percent||18}));
  const invTotalValue=activeInvProds.reduce((s,p)=>s+(p.current_stock||0)*(p.buying_price||0),0);
  const invLowStock=activeInvProds.filter(p=>(p.current_stock||0)<=(p.min_stock||0)&&(p.min_stock||0)>0);
  const invTotalInvested=invTxns.filter(t=>t.type==="stock_in").reduce((s,t)=>s+(t.total_cost||0),0);
  const invCatChart=invCats.map(c=>{const ps=activeInvProds.filter(p=>p.category_id===c.id);const val=ps.reduce((s,p)=>s+(p.current_stock||0)*(p.buying_price||0),0);return{name:c.name,value:val,color:c.color};}).filter(c=>c.value>0);
  const exportInvCSV=()=>{let csv="SKU,Name,Category,Unit,Stock,Buy Price,Sell Price,Value\n";activeInvProds.forEach(p=>{csv+=`${p.sku},${p.name},${p.category_name||'-'},${p.unit},${p.current_stock},${p.buying_price},${p.selling_price},${(p.current_stock||0)*(p.buying_price||0)}\n`;});const b=new Blob([csv],{type:"text/csv"});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download="Inventory_"+CM.replace(" ","_")+".csv";a.click();URL.revokeObjectURL(u);};

  // Requisitions
  const createReq=async()=>{if(!frmParty.name){setFrmErr("Required");return;}const vi=frmItems.filter(i=>i.desc||i.rate>0);if(!vi.length){setFrmErr("Add items");return;}setSaving(true);await db.addRequisition({number:nextNum("REQ",reqs),date:frmDate,requestedBy:user.displayName,vendor:frmParty,type:frmType,project:frmProj,subtotal:calcSub(vi),tax:calcTax(vi),total:calcTot(vi),notes:frmNotes},vi);await log("create","requisition",null,"REQ for "+frmParty.name);await loadAll();resetForm();setSaving(false);setModal(null);};
  const submitReq=async(id,n)=>{setSaving(true);await db.updateRequisitionStatus(id,"submitted");await log("submit","requisition",id,n);await loadAll();setSaving(false);};
  const approveReq=async(id,n)=>{setSaving(true);await db.updateRequisitionStatus(id,"approved",user.displayName);await log("approve","requisition",id,n);await loadAll();setSaving(false);};
  const rejectReq=async(id,n)=>{setSaving(true);await db.updateRequisitionStatus(id,"rejected",user.displayName);await log("reject","requisition",id,n);await loadAll();setSaving(false);};
  const convertReqToPO=async(req)=>{setSaving(true);const items=await db.getRequisitionItems(req.id);const fi=items.map(i=>({desc:i.description,hsn:i.hsn,qty:i.qty,rate:i.rate,gst:i.gst_percent}));const pn=nextNum("PO",pos);await db.addPurchaseOrder({number:pn,date:new Date().toISOString().slice(0,10),vendor:req.vendor,type:req.type,project:req.project,subtotal:req.subtotal,tax:req.tax,total:req.total,notes:"From "+req.number,requisitionId:req.id},fi);await db.updateRequisitionStatus(req.id,"converted");await log("convert","requisition",req.id,req.number+" -> "+pn);await loadAll();setSaving(false);};

