  const createPO=async()=>{if(!frmParty.name){setFrmErr("Required");return;}const vi=frmItems.filter(i=>i.desc||i.rate>0);if(!vi.length){setFrmErr("Add items");return;}setSaving(true);await db.addPurchaseOrder({number:nextNum("PO",pos),date:frmDate,deliveryDate:frmDue,vendor:frmParty,type:frmType,project:frmProj,subtotal:calcSub(vi),tax:calcTax(vi),total:calcTot(vi),notes:frmNotes},vi);await log("create","po",null,"PO for "+frmParty.name);await loadAll();resetForm();setSaving(false);setModal(null);};
