      {modal==="editPO"&&<Md title="Edit Purchase Order" onClose={()=>{resetForm();setEditPOId(null);setEditPOItems([]);setModal(null);}} wide>{renderPartyForm("Vendor")}<div className="my-4 border-t border-gray-100 pt-4">{renderDocForm({showDue:true,dueLabel:"Delivery Date"})}</div><div className="my-4 border-t border-gray-100 pt-4"><h4 className="text-sm font-semibold text-gray-700 mb-2">Items</h4><ItemsEditor items={editPOItems} setItems={setEditPOItems} products={searchableProducts} showProductSearch={true}/></div><div className="my-3"><label className={LC}>Notes</label><input className={IC} value={frmNotes} onChange={e=>setFrmNotes(e.target.value)}/></div>{frmErr&&<p className="text-red-500 text-sm">{frmErr}</p>}<button onClick={saveEditPO} disabled={saving} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white font-semibold rounded-xl">Save Changes</button></Md>}

