      {/* Bank Reconciliation Modal — preview then confirm */}
      {modal==="reconcile"&&<Md title="Reconcile to Bank Balance" onClose={()=>{setRecTrueBal("");setModal(null);}} wide><div className="space-y-4"><div className="bg-amber-50 rounded-xl p-3 text-xs text-amber-700">Review the figures below, enter your real closing bank balance, then confirm. Nothing changes until you click Confirm.</div><div className="grid grid-cols-3 gap-3"><div className="bg-gray-50 rounded-xl p-3"><p className="text-[10px] text-gray-500 uppercase font-bold">Total Balance</p><p className="text-lg font-bold text-violet-800">{fmt(bal)}</p></div><div className="bg-gray-50 rounded-xl p-3"><p className="text-[10px] text-gray-500 uppercase font-bold">Liquid Reserve</p><p className="text-lg font-bold text-[#8a6e2b]">{fmt(liq)}</p></div><div className="bg-gray-50 rounded-xl p-3"><p className="text-[10px] text-gray-500 uppercase font-bold">Allocated</p><p className="text-lg font-bold text-amber-700">{fmt(totAlloc)}</p></div></div><div className="border border-gray-100 rounded-xl p-3"><p className="text-sm font-semibold text-gray-700 mb-2">Transactions to normalize → "Available"</p><div className="flex justify-between text-sm"><span className="text-gray-500">Reserve-sourced debits ({recReserveTxs.length})</span><span className="font-semibold">{fmt(recReserveSum)}</span></div><div className="flex justify-between text-sm"><span className="text-gray-500">Project-fund debits ({recProjFundTxs.length})</span><span className="font-semibold">{fmt(recProjFundSum)}</span></div><p className="text-[11px] text-gray-400 mt-2">These keep their amount and date — only their fund tag becomes "Available". The Liquid Reserve will be set to {fmt(0)} (display-only going forward). Project budgets are kept.</p></div><div><label className={LC}>True closing bank balance (from your statement)*</label><input type="number" className={IC} value={recTrueBal} onChange={e=>setRecTrueBal(e.target.value)} placeholder="e.g. 125000"/></div>{recTrueBal!==""&&!isNaN(Number(recTrueBal))&&<div className="bg-violet-50 rounded-xl p-3 text-sm"><div className="flex justify-between"><span className="text-gray-600">Total Balance</span><span className="font-semibold">{fmt(bal)} → {fmt(Number(recTrueBal))}</span></div><div className="flex justify-between"><span className="text-gray-600">Adjustment entry</span><span className={`font-semibold ${Number(recTrueBal)-bal>=0?"text-emerald-600":"text-red-500"}`}>{Number(recTrueBal)-bal>=0?"+":""}{fmt(Number(recTrueBal)-bal)}</span></div></div>}<button onClick={doReconcile} disabled={saving||recTrueBal===""||isNaN(Number(recTrueBal))} className="w-full py-3 bg-amber-600 hover:bg-amber-700 disabled:opacity-50 text-white font-semibold rounded-xl">Confirm Reconciliation</button></div></Md>}

